import Foundation

// StrainWhoopCalibrationFixtures.swift. Eight days of heart rate read off the WHOOP app's own Heart Rate screen (screenshots,
// one value per minute, taken from the middle of the drawn line) together with the resting heart rate and the Day Strain the
// WHOOP app showed for each of those days. Used by StrainWhoopCalibrationTests to hold `banisterSedentaryHRR` to the data it was
// calibrated on.
//
// `hr` is a run of minutes from the start of the plotted cycle: a number is the bpm of the next minute, `_N` skips N minutes (the
// strap was off, or the screenshot had a gap). One wearer, 26 Oct to 10 Nov 2026. Reading the curve off pixels puts the mean heart
// rate about 3 bpm high and the peaks 3 to 11 bpm low, which is why the tests keep a tolerance rather than expecting equality.
struct WhoopCalibrationDay {
    let label: String
    let restingHR: Double
    let whoopDayStrain: Double   // 0-21, as the WHOOP app showed it
    let hr: String

    /// The minutes as HR samples, one per recorded minute, with the gaps kept.
    var samples: [(minute: Int, bpm: Int)] {
        var out: [(Int, Int)] = []; var m = 0
        for tok in hr.split(separator: " ") {
            if tok.hasPrefix("_") { m += Int(tok.dropFirst()) ?? 0 } else if let b = Int(tok) { out.append((m, b)); m += 1 }
        }
        return out
    }
}

